1	import React, { createContext, useContext, useEffect, useState } from 'react';
2	import { supabase } from '../lib/supabase';
3	import { useAuth } from './AuthContext';
4	import { logError } from '../lib/logger'
5	
6	export interface Notification {
7	    id: string;
8	    type: 'status_change' | 'message' | 'payment' | 'system';
9	    title: string;
10	    message: string;
11	    link?: string;
12	    read_at: string | null;
13	    created_at: string;
14	}
15	
16	interface NotificationContextType {
17	    notifications: Notification[];
18	    unreadCount: number;
19	    markAsRead: (id: string) => Promise<void>;
20	    markAllAsRead: () => Promise<void>;
21	}
22	
23	const NotificationContext = createContext<NotificationContextType | undefined>(undefined);
24	
25	export function NotificationProvider({ children }: { children: React.ReactNode }) {
26	    const { user } = useAuth();
27	    const [notifications, setNotifications] = useState<Notification[]>([]);
28	    const [dbAvailable, setDbAvailable] = useState(true);
29	
30	    const unreadCount = notifications.filter(n => !n.read_at).length;
31	
32	    useEffect(() => {
33	        if (!user) {
34	            return () => {
35	                setNotifications([]);
36	            };
37	        }
38	
39	        let isActive = true;
40	
41	        const createId = () => (typeof crypto !== 'undefined' && 'randomUUID' in crypto)
42	            ? crypto.randomUUID()
43	            : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
44	
45	        const loadNotifications = async () => {
46	            if (!dbAvailable) return;
47	            const { data, error } = await supabase
48	                .from('notifications')
49	                .select('*')
50	                .eq('user_id', user.id)
51	                .order('created_at', { ascending: false })
52	                .limit(50);
53	
54	            if (!isActive) return;
55	
56	            if (error) {
57	                if (error.code === '42P01' || error.message?.toLowerCase().includes('does not exist')) {
58	                    setDbAvailable(false);
59	                }
60	                return;
61	            }
62	
63	            if (data) setNotifications(data);
64	        };
65	
66	        loadNotifications();
67	
68	        const dbChannel = dbAvailable ? supabase
69	            .channel('notifications-changes')
70	            .on(
71	                'postgres_changes',
72	                {
73	                    event: '*',
74	                    schema: 'public',
75	                    table: 'notifications',
76	                    filter: `user_id=eq.${user.id}`
77	                },
78	                (payload) => {
79	                    if (payload.eventType === 'INSERT') {
80	                        setNotifications(prev => [payload.new as Notification, ...prev]);
81	                    } else if (payload.eventType === 'UPDATE') {
82	                        setNotifications(prev => prev.map(n => n.id === payload.new.id ? payload.new as Notification : n));
83	                    }
84	                }
85	            )
86	            .subscribe() : null;
87	
88	        const broadcastChannel = supabase
89	            .channel(`user:${user.id}`)
90	            .on('broadcast', { event: 'new_notification' }, (payload) => {
91	                const data = payload.payload as Partial<Notification> & { message?: string; link?: string; title?: string; type?: Notification['type'] };
92	                const createdAt = new Date().toISOString();
93	                const notification: Notification = {
94	                    id: data.id ?? createId(),
95	                    type: data.type ?? 'system',
96	                    title: data.title ?? 'Notificação',
97	                    message: data.message ?? '',
98	                    link: data.link,
99	                    read_at: null,
100	                    created_at: data.created_at ?? createdAt
101	                };
102	                setNotifications(prev => [notification, ...prev]);
103	            })
104	            .subscribe();
105	
106	        return () => {
107	            isActive = false;
108	            if (dbChannel) supabase.removeChannel(dbChannel);
109	            supabase.removeChannel(broadcastChannel);
110	        };
111	    }, [user, dbAvailable]);
112	
113	    const markAsRead = async (id: string) => {
114	        // Optimistic update
115	        setNotifications(prev => prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n));
116	
117	        if (!dbAvailable) return;
118	
119	        const { error } = await supabase
120	            .from('notifications')
121	            .update({ read_at: new Date().toISOString() })
122	            .eq('id', id);
123	
124	        if (error) logError('Error marking notification as read:', error);
125	    };
126	
127	    const markAllAsRead = async () => {
128	        // Optimistic
129	        setNotifications(prev => prev.map(n => ({ ...n, read_at: new Date().toISOString() })));
130	
131	        if (!dbAvailable) return;
132	
133	        const { error } = await supabase
134	            .from('notifications')
135	            .update({ read_at: new Date().toISOString() })
136	            .eq('user_id', user?.id)
137	            .is('read_at', null);
138	
139	        if (error) logError('Error marking all as read:', error);
140	    };
141	
142	    return (
143	        <NotificationContext.Provider value={{ notifications, unreadCount, markAsRead, markAllAsRead }}>
144	            {children}
145	        </NotificationContext.Provider>
146	    );
147	}
148	
149	// eslint-disable-next-line react-refresh/only-export-components
150	export const useNotifications = () => {
151	    const context = useContext(NotificationContext);
152	    if (context === undefined) {
153	        throw new Error('useNotifications must be used within a NotificationProvider');
154	    }
155	    return context;
156	};
