17	export default function RateModal({ isOpen, onClose, onSubmit, targetName, targetPhotoUrl, title, subtitle }: RateModalProps) {
18	    const [rating, setRating] = useState(5);
19	    const [comment, setComment] = useState('');
20	    const [submitting, setSubmitting] = useState(false);
21	    const trapRef = useFocusTrap(isOpen);
