107	
108	                <button
109	                    onClick={handleSubmit}
110	                    disabled={submitting}
111	                    className="w-full bg-black text-white py-4 rounded-xl font-black uppercase tracking-wide hover:bg-green-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center gap-2"
112	                >
113	                    {submitting ? <Loader2 className="animate-spin" /> : null}
114	                    {submitting ? 'Enviando...' : 'Enviar Avaliação'}
115	                </button>
116	            </div>
117	        </div>
118	    );
