10	export default function WorkerPublicProfile() {
11	    const { id } = useParams();
12	    const navigate = useNavigate();
13	    interface WorkerProfileData {
14	        id: string;
15	        full_name: string;
16	        bio?: string;
17	        city?: string;
18	        level?: number;
19	        xp?: number;
20	        completed_jobs_count?: number;
