52	
53	    useEffect(() => {
54	        if (id) {
55	            fetchProfile();
56	            // Track View
57	            import('../../services/analytics').then(({ AnalyticsService }) => {
58	                AnalyticsService.trackProfileView(id);
59	            });
60	        }
61	    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchProfile usa state setters estaveis, so precisa re-executar quando id muda
62	    }, [id]);
63	
64	    const fetchProfile = async () => {
65	        try {
66	            // Fetch Profile
67	            const { data: profileData, error: profileError } = await supabase
68	                .from('workers')
69	                .select('id, full_name, bio, city, level, xp, completed_jobs_count, recommendation_score, rating_average, reviews_count, tags, created_at, avatar_url')
70	                .eq('id', id)
71	                .single();
72	
73	            if (profileError) throw profileError;
74	
75	            // Map fields for UI consistency
76	            const mappedProfile = {
77	                ...profileData,
78	                location: profileData.city,
79	                joined_at: profileData.created_at,
80	                photo_url: profileData.avatar_url,
81	                completed_jobs: profileData.completed_jobs_count
