90	                .eq('reviewed_id', id)
91	                .order('created_at', { ascending: false });
92	
93	            if (reviewsData && reviewsData.length > 0) {
94	                // Manually fetch company names (as per existing logic)
95	                const reviewerIds = [...new Set(reviewsData.map(r => r.reviewer_id))];
96	                const { data: companies } = await supabase
97	                    .from('companies')
98	                    .select('id, name')
99	                    .in('id', reviewerIds);
100	
101	                const companyMap = new Map((companies || []).map(c => [c.id, c.name]));
102	
103	                // Attach names
