105	                    ...r,
106	                    company: { name: companyMap.get(r.reviewer_id) || 'Empresa' }
107	                }));
108	                setReviews(enrichedReviews);
109	            } else {
110	                setReviews([]);
111	            }
112	
113	            // Fetch History (Completed Jobs)
114	            const { data: historyData } = await supabase
115	                .from('applications')
116	                .select('*, job:jobs(title, company:companies(name))')
117	                .eq('worker_id', id)
118	                .in('status', ['hired', 'completed'])
119	                .limit(5);
